"use client";
/**
 * Clio dashboard: a FoundKeep board built from the Clio widgets. Saves this week, the week by day, the reading queue
 * with what's next, quiet hours, the reading goal, folders, the month, what's playing, collections and Ask Kit. The
 * board builds itself in tile by tile; Focus turns the whole board dark, and quiet hours darken their own tile.
 *
 * Every piece of data and copy is a prop. The sample data is made up and sits around the current time.
 */
import {
  type CSSProperties,
  type FormEvent,
  type ReactNode,
  useEffect,
  useId,
  useState,
} from "react";
import { ClioBarWeek } from "./bar-week";
import { ClioCalendar } from "./calendar";
import { type ClioFoundKeepData, clioAskSaves, clioFoundKeepSample } from "./dashboard-data";
import { ClioList } from "./list";
import { ClioNowPlaying } from "./now-playing";
import { ClioRing } from "./ring";
import { ClioStat } from "./stat";
import {
  type ClioColorOverrides,
  type ClioMotion,
  ClioTheme,
  ClioTile,
  clioTileAliveDelay,
  useClioAlive,
} from "./theme";
import { ClioSwitch, ClioToggle } from "./toggle";
import { CLIO_MOTION, type ClioMode } from "./tokens";

const CSS = `
.clio-board{container-type:inline-size;min-height:100%;width:100%}
.clio-board__inner{max-width:1260px;margin:0 auto;padding:44px 40px 56px}
.clio-board__head{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;margin:0 0 26px;animation:clio-rise var(--clio-rise-ms) var(--clio-rise-ease) both}
.clio-board__brand{margin:0 0 14px;font-size:14px;font-weight:600;letter-spacing:-.01em;color:var(--clio-ink);transition:color var(--clio-mode-ms) var(--clio-mode-ease)}
