.clio-board__focus{display:flex;align-items:center;gap:10px;padding:8px 10px 8px 14px;border-radius:999px;background:var(--clio-tile);box-shadow:0 0 0 1px var(--clio-hairline),var(--clio-shadow);font-size:13px;font-weight:500;cursor:pointer;transition:background-color var(--clio-mode-ms) var(--clio-mode-ease),box-shadow var(--clio-mode-ms) var(--clio-mode-ease)}
.clio-board__grid{display:grid;gap:var(--clio-gap);grid-template-columns:minmax(0,1fr)}
