  .clio-board__grid{grid-template-columns:repeat(4,minmax(0,1fr));grid-auto-rows:minmax(186px,auto);grid-auto-flow:dense}
  .clio-board__grid>[data-span="m"]{grid-column:span 2}
  .clio-board__grid>[data-span="l"]{grid-column:span 2;grid-row:span 2}
  .clio-board__grid>[data-area="ask"]{grid-column:span 4}
}
@container (min-width:1100px){
  .clio-board__grid{grid-template-columns:repeat(6,minmax(0,1fr));grid-template-rows:repeat(3,minmax(190px,auto));grid-auto-flow:row;grid-template-areas:"stat week week queue queue quiet" "ring folders folders queue queue cal" "play play collections collections ask ask"}
  .clio-board__grid>[data-area="stat"]{grid-area:stat}.clio-board__grid>[data-area="week"]{grid-area:week}.clio-board__grid>[data-area="queue"]{grid-area:queue}.clio-board__grid>[data-area="quiet"]{grid-area:quiet}
  .clio-board__grid>[data-area="ring"]{grid-area:ring}.clio-board__grid>[data-area="folders"]{grid-area:folders}.clio-board__grid>[data-area="cal"]{grid-area:cal}
  .clio-board__grid>[data-area="play"]{grid-area:play}.clio-board__grid>[data-area="collections"]{grid-area:collections}.clio-board__grid>[data-area="ask"]{grid-area:ask}
}
@container (max-width:639px){
  .clio-board__inner{padding:24px 16px 40px}
  .clio-board__title{font-size:28px}
  .clio-board__head{align-items:flex-start;flex-direction:column;gap:14px}
}
.clio-folders__rows{list-style:none;margin:auto 0 0;padding:12px 0 0;display:flex;flex-direction:column;gap:11px}
.clio-folders__row{display:grid;grid-template-columns:minmax(80px,1.1fr) minmax(0,2fr) 34px 26px;align-items:center;gap:10px}
