.clio-slip__name{margin:0;font-size:13px;font-weight:500;line-height:1.25;letter-spacing:-.006em}
.clio-slip__count{margin:0;font-size:24px}
@container (max-width:420px){.clio-slips{grid-template-columns:minmax(0,1fr)}.clio-slip{min-height:0;flex-direction:row;align-items:baseline;transform:none}}
.clio-ask__form{display:flex;gap:8px;margin-top:12px}
.clio-ask__field{flex:1;min-width:0;height:38px;padding:0 12px;border:0;border-radius:var(--clio-radius-inner);background:var(--clio-raised);box-shadow:inset 0 0 0 1px var(--clio-hairline-strong);color:var(--clio-ink);font:inherit;font-size:13px;transition:box-shadow 160ms ease,background-color var(--clio-mode-ms) var(--clio-mode-ease)}
.clio-ask__field::placeholder{color:var(--clio-ink-tertiary)}
.clio-ask__field:focus{outline:none;box-shadow:inset 0 0 0 1.5px var(--clio-accent)}
.clio-ask__go{all:unset;flex:none;display:inline-grid;place-items:center;height:38px;padding:0 14px;border-radius:var(--clio-radius-inner);background:var(--clio-accent);color:var(--clio-on-accent);font-size:13px;font-weight:500;cursor:pointer;transition:background-color 160ms ease,transform var(--clio-press-ms) var(--clio-press-ease)}
.clio-ask__go:hover{background:var(--clio-accent-hover)}
.clio-ask__go:active{background:var(--clio-accent-pressed);transform:scale(.97)}
.clio-ask__go:focus-visible{outline:2px solid var(--clio-accent);outline-offset:2px}
.clio-ask__out{margin-top:auto;padding-top:12px;min-height:0}
.clio-ask__answer{margin:0;font-size:13px;line-height:1.5;color:var(--clio-ink);animation:clio-ask-in 520ms var(--clio-alive-ease) both}
@keyframes clio-ask-in{from{opacity:0;transform:translate3d(0,8px,0)}to{opacity:1;transform:none}}
.clio-ask__chips{display:flex;flex-wrap:wrap;gap:6px}
.clio-ask__chip{all:unset;display:inline-flex;align-items:center;min-height:28px;padding:0 11px;border-radius:999px;background:var(--clio-track);font-size:12px;line-height:1.2;color:var(--clio-ink-secondary);cursor:pointer;transition:background-color 160ms ease,color 160ms ease,transform var(--clio-press-ms) var(--clio-press-ease)}
.clio-ask__chip:hover{background:var(--clio-hairline-strong);color:var(--clio-ink)}
.clio-ask__chip:active{transform:scale(.97)}
.clio-ask__chip:focus-visible{outline:2px solid var(--clio-accent);outline-offset:2px}
.clio-ask__again{all:unset;margin-top:8px;font-size:12px;font-weight:500;color:var(--clio-accent-ink);cursor:pointer;border-radius:4px}
.clio-ask__again:focus-visible{outline:2px solid var(--clio-accent);outline-offset:2px}
@media (prefers-reduced-motion:reduce){.clio-board__head{animation:none}.clio-folders__bar i{transition:none}.clio-ask__answer{animation:none}}
`;

export interface ClioDashboardCopy {
  brand: string;
  title: string;
  focus: string;
  saves: string;
  savesDetail: (thisWeek: number, lastWeek: number) => string;
  week: string;
  queue: string;
  markRead: string;
  undo: string;
  quiet: string;
  quietOn: (until: string) => string;
  quietOff: string;
  reading: string;
  readingOf: (goal: number) => string;
  folders: string;
  foldersMeta: (count: number) => string;
  calendarMeta: (days: number) => string;
  calendarMarked: string;
  listening: string;
  collections: string;
  collectionsMeta: string;
  ask: string;
  askField: string;
  askButton: string;
  askAgain: string;
}

export const CLIO_DASHBOARD_COPY: ClioDashboardCopy = {
  brand: "FoundKeep",
  title: "Your week in saves",
  focus: "Focus",
  saves: "Saved this week",
  savesDetail: (thisWeek, lastWeek) =>
    thisWeek === lastWeek
      ? "Same as last week"
      : `${Math.abs(thisWeek - lastWeek)} ${thisWeek > lastWeek ? "more" : "fewer"} than last week`,
  week: "Saves by day",
  queue: "Reading queue",
  markRead: "Mark read",
  undo: "Undo",
  quiet: "Quiet hours",
  quietOn: (until) => `Nudges wait until ${until}`,
  quietOff: "Nudges arrive as usual",
  reading: "Read this week",
  readingOf: (goal) => `of ${goal}`,
  folders: "Folders",
  foldersMeta: (count) => `${count} this week`,
  calendarMeta: (days) => `${days} days read`,
  calendarMarked: "read",
  listening: "Listening",
  collections: "Collections",
  collectionsMeta: "Lists you keep with others",
  ask: "Ask Kit",
  askField: "Ask Kit about your saves",
  askButton: "Ask",
  askAgain: "Ask something else",
};

export interface ClioDashboardProps {
  /** Everything the board shows; made-up sample data around `now` by default. */
  data?: ClioFoundKeepData;
  /** The time the board is shown at. Left out, it follows the clock from the moment it mounts. */
  now?: Date | number;
  /** Paper or focus for the whole board (controlled). */
  mode?: ClioMode;
  defaultMode?: ClioMode;
  onModeChange?: (mode: ClioMode) => void;
  /** Quiet hours, on or off (controlled). */
  quiet?: boolean;
  defaultQuiet?: boolean;
  onQuietChange?: (on: boolean) => void;
  /** Kit's answer to a question; by default it looks through the sample library. */
  onAsk?: (question: string) => string;
  copy?: Partial<ClioDashboardCopy>;
  motion?: ClioMotion;
  colors?: ClioColorOverrides;
  /** Build the board in tile by tile. */
  rise?: boolean;
  className?: string;
  style?: CSSProperties;
}

/** The current time from mount on, a minute at a time; null on the server and before mount. */
function useClock(fixed?: Date | number): number | null {
  const [now, setNow] = useState<number | null>(
    fixed === undefined ? null : new Date(fixed).getTime(),
  );
  useEffect(() => {
    if (fixed !== undefined) return setNow(new Date(fixed).getTime());
    setNow(Date.now());
    const timer = setInterval(() => setNow(Date.now()), 30_000);
    return () => clearInterval(timer);
  }, [fixed]);
  return now;
}

const TILE_DELAY = 110;
const riseAt = (index: number) => TILE_DELAY + index * CLIO_MOTION.rise.stagger;

interface BoardTile {
  index: number;
  rise: boolean;
}

function Folders({
  label,
  meta,
  rows,
  index,
  rise,
}: BoardTile & { label: string; meta: ReactNode; rows: ClioFoundKeepData["folders"] }) {
  const alive = useClioAlive(clioTileAliveDelay(undefined, riseAt(index)));
  const max = Math.max(1, ...rows.map((r) => r.count));
  return (
    <ClioTile
      label={label}
      meta={meta}
      rise={rise}
      riseDelay={riseAt(index)}
      className="clio-folders"
      data-span="m"
      data-area="folders"
      data-alive={alive ? "" : undefined}
    >
      <ul className="clio-folders__rows">
        {rows.map((row, i) => (
          <li
            key={row.name}
            className="clio-folders__row"
            style={{ ["--clio-row-delay" as string]: `${i * CLIO_MOTION.alive.stagger}ms` }}
          >
            <span className="clio-folders__name">{row.name}</span>
            <span className="clio-folders__bar" aria-hidden="true">
              <i style={{ ["--clio-share" as string]: (row.count / max).toFixed(3) }} />
            </span>
            <span className="clio-folders__count">
              {row.count}
              <span className="clio-sr"> saves</span>
            </span>
            <span className="clio-folders__added" data-none={row.added ? undefined : ""}>
              {row.added ? `+${row.added}` : "0"}
              <span className="clio-sr"> new this week</span>
            </span>
          </li>
        ))}
      </ul>
    </ClioTile>
  );
}

const TILTS = ["-1.2deg", "0.7deg", "-0.4deg"];

function Collections({
  label,
  meta,
  rows,
  index,
  rise,
}: BoardTile & { label: string; meta: ReactNode; rows: ClioFoundKeepData["collections"] }) {
  return (
    <ClioTile
      label={label}
      meta={meta}
      rise={rise}
      riseDelay={riseAt(index)}
      className="clio-collections"
      data-span="m"
      data-area="collections"
    >
      <ul className="clio-slips">
        {rows.map((row, i) => (
          <li
            key={row.name}
            className="clio-slip"
            style={{ ["--clio-slip-tilt" as string]: TILTS[i % TILTS.length] }}
          >
            <p className="clio-slip__name">{row.name}</p>
            <div>
              <p className="clio-numeral clio-slip__count">
                {row.saves}
                <span className="clio-sr"> saves</span>
              </p>
              <p className="clio-caption">{row.sharing}</p>
            </div>
          </li>
        ))}
      </ul>
    </ClioTile>
  );
}

function AskKit({
  copy,
  data,
  onAsk,
  index,
  rise,
}: BoardTile & {
  copy: ClioDashboardCopy;
  data: ClioFoundKeepData["ask"];
  onAsk?: (q: string) => string;
}) {
  const [question, setQuestion] = useState("");
  const [answer, setAnswer] = useState<{ q: string; a: string } | null>(null);
  const fieldId = useId();
  const ask = (q: string) => {
    const text = q.trim();
    if (!text) return;
    const prepared = data.suggestions.find((s) => s.question.toLowerCase() === text.toLowerCase());
    setQuestion(text);
    setAnswer({
      q: text,
      a: onAsk ? onAsk(text) : (prepared?.answer ?? clioAskSaves(text, data.library)),
    });
  };
  const submit = (event: FormEvent) => {
    event.preventDefault();
    ask(question);
  };
  return (
    <ClioTile
      label={copy.ask}
      rise={rise}
      riseDelay={riseAt(index)}
      className="clio-ask"
      data-span="m"
      data-area="ask"
    >
      <form className="clio-ask__form" onSubmit={submit} role="search">
        <label className="clio-sr" htmlFor={fieldId}>
          {copy.askField}
        </label>
        <input
          id={fieldId}
          className="clio-ask__field"
          value={question}
          onChange={(e) => setQuestion(e.target.value)}
          placeholder={data.placeholder}
          autoComplete="off"
        />
        <button type="submit" className="clio-ask__go">
          {copy.askButton}
        </button>
      </form>
      <div className="clio-ask__out" aria-live="polite">
        {answer ? (
          <>
            <p key={answer.q} className="clio-ask__answer">
              {answer.a}
            </p>
            <button
              type="button"
              className="clio-ask__again"
              onClick={() => {
                setAnswer(null);
                setQuestion("");
              }}
            >
              {copy.askAgain}
            </button>
          </>
        ) : (
          <div className="clio-ask__chips">
            {data.suggestions.map((s) => (
              <button
                key={s.question}
                type="button"
                className="clio-ask__chip"
                onClick={() => ask(s.question)}
              >
                {s.question}
              </button>
            ))}
          </div>
        )}
      </div>
    </ClioTile>
  );
}

export function ClioDashboard({
  data,
  now,
  mode,
  defaultMode = "paper",
  onModeChange,
  quiet,
  defaultQuiet = false,
  onQuietChange,
  onAsk,
  copy: copyOverrides,
  motion,
  colors,
  rise = true,
  className,
  style,
}: ClioDashboardProps) {
  const copy = { ...CLIO_DASHBOARD_COPY, ...copyOverrides };
  const clock = useClock(now);
  const [ownMode, setOwnMode] = useState<ClioMode>(defaultMode);
  const board = mode ?? ownMode;
  const setMode = (next: ClioMode) => {
    if (mode === undefined) setOwnMode(next);
    onModeChange?.(next);
  };
  const focusId = useId();
  const d = data ?? (clock === null ? null : clioFoundKeepSample(clock));
  const dateLabel =
    clock === null
      ? " "
      : new Intl.DateTimeFormat("en-GB", { weekday: "long", day: "numeric", month: "long" }).format(
          new Date(clock),
        );

  return (
    <ClioTheme
      mode={board}
      motion={motion}
      colors={colors}
      className={className ? `clio-board ${className}` : "clio-board"}
      style={style}
    >
      <style>{CSS}</style>
      <div className="clio-board__inner">
        <header className="clio-board__head">
          <div>
            <p className="clio-board__brand">{copy.brand}</p>
            <h1 className="clio-board__title">{copy.title}</h1>
            <p className="clio-caption">{dateLabel}</p>
          </div>
          {/* The label is part of the pill, so the whole pill is a target. */}
          <label className="clio-board__focus" htmlFor={focusId}>
            <span>{copy.focus}</span>
            <ClioSwitch
              id={focusId}
              checked={board === "focus"}
              onCheckedChange={(on) => setMode(on ? "focus" : "paper")}
              label={copy.focus}
            />
          </label>
        </header>
        {d ? (
          <div className="clio-board__grid">
            <ClioStat
              label={copy.saves}
              value={d.saves.thisWeek}
              detail={copy.savesDetail(d.saves.thisWeek, d.saves.lastWeek)}
              trend={d.saves.thisWeek >= d.saves.lastWeek ? "up" : "down"}
              rise={rise}
              riseDelay={riseAt(0)}
              data-span="s"
              data-area="stat"
            />
            <ClioBarWeek
              label={copy.week}
              days={d.week}
              today={d.today}
              rise={rise}
              riseDelay={riseAt(1)}
              data-span="m"
              data-area="week"
            />
            <ClioList
              label={copy.queue}
              items={d.queue}
              now={clock}
              actionLabel={copy.markRead}
              undoLabel={copy.undo}
              rise={rise}
              riseDelay={riseAt(2)}
              data-span="l"
              data-area="queue"
            />
            <ClioToggle
              label={copy.quiet}
              checked={quiet}
              defaultChecked={defaultQuiet}
              onCheckedChange={onQuietChange}
              detailOn={copy.quietOn(d.quiet.until)}
              detailOff={copy.quietOff}
              rise={rise}
              riseDelay={riseAt(3)}
              data-span="s"
              data-area="quiet"
            />
            <ClioRing
              label={copy.reading}
              value={d.reading.read}
              max={d.reading.goal}
              of={copy.readingOf(d.reading.goal)}
              valueText={`${d.reading.read} of ${d.reading.goal} read`}
              size={116}
              rise={rise}
              riseDelay={riseAt(4)}
              data-span="s"
              data-area="ring"
            />
            <Folders
              label={copy.folders}
              meta={copy.foldersMeta(d.folders.reduce((n, f) => n + f.added, 0))}
              rows={d.folders}
              index={5}
              rise={rise}
            />
            <ClioCalendar
              year={d.calendar.year}
              month={d.calendar.month}
              today={d.calendar.today}
              marked={d.calendar.marked}
              markedLabel={copy.calendarMarked}
              meta={copy.calendarMeta(d.calendar.marked.length)}
              rise={rise}
              riseDelay={riseAt(6)}
              data-span="s"
              data-area="cal"
            />
            <ClioNowPlaying
              label={copy.listening}
              title={d.listening.title}
              source={d.listening.source}
              duration={d.listening.duration}
              defaultPosition={d.listening.position}
              rise={rise}
              riseDelay={riseAt(7)}
              data-span="m"
              data-area="play"
            />
            <Collections
              label={copy.collections}
              meta={copy.collectionsMeta}
              rows={d.collections}
              index={8}
              rise={rise}
            />
            <AskKit copy={copy} data={d.ask} onAsk={onAsk} index={9} rise={rise} />
          </div>
        ) : null}
      </div>
    </ClioTheme>
  );
}

/**
 * Made-up sample data for the FoundKeep board: one person's week of saving and reading, laid out around the time it
 * is shown, so the queue always has something next and the week ends today. None of it is anyone's real library.
 */
import { clioIsoDate } from "./calendar";
import type { ClioListItem } from "./list";

export interface ClioFoundKeepSave {
  title: string;
  folder: string;
  /** Words it can be found by, beside its title. */
  tags: string[];
}

export interface ClioFoundKeepData {
  saves: { thisWeek: number; lastWeek: number };
  /** Monday to Sunday. Days still to come have no count. */
  week: { label: string; short: string; value: number | null }[];
  /** Index of today in `week`. */
