/** The board's sample data around `now`. */
export function clioFoundKeepSample(now: Date | number = Date.now()): ClioFoundKeepData {
  const at = new Date(now);
  const t = at.getTime();
  const today = (at.getDay() + 6) % 7; // Monday is 0.
  const week = WEEK.map((label, i) => ({
    label,
    short: label.slice(0, 1),
    value: i <= today ? (SAVES[i] ?? 0) : null,
  }));
  const thisWeek = week.reduce((sum, d) => sum + (d.value ?? 0), 0);
  const minutes = (m: number) => t + m * 60_000;
  const tomorrowAt8 = new Date(at);
  tomorrowAt8.setDate(at.getDate() + 1);
  tomorrowAt8.setHours(8, 0, 0, 0);
  const iso = clioIsoDate(at);
  const [year, month, day] = iso.split("-").map(Number) as [number, number, number];
  const marked: string[] = [];
  for (let d = 1; d < day; d++)
    if ((d * 7 + 3) % 5 < 3) marked.push(`${iso.slice(0, 8)}${String(d).padStart(2, "0")}`);

  return {
    saves: { thisWeek, lastWeek: Math.max(0, thisWeek - 9) },
    week,
    today,
    reading: { read: 5, goal: 8 },
    queue: [
      { id: "tabs", title: "Why we keep tabs open", detail: "7 min read", at: minutes(25) },
