/** Kit's answer from the library alone: the saves whose title or words match the question. */
export function clioAskSaves(question: string, library: readonly ClioFoundKeepSave[]): string {
  const words = question
    .toLowerCase()
    .split(/[^\p{L}\p{N}]+/u)
    .filter((w) => w.length > 1 && !STOP.has(w));
  if (!words.length)
    return "Ask about a topic, a place or a folder, and Kit looks through your saves.";
  const found = library.filter((save) => {
    const hay = `${save.title} ${save.folder} ${save.tags.join(" ")}`.toLowerCase();
    return words.some((w) => hay.includes(w));
  });
  if (!found.length)
    return `Nothing in your saves mentions “${question.trim().replace(/\?$/, "")}” yet.`;
  const titles = found.slice(0, 3).map((s) => s.title);
  const list =
    titles.length === 1
      ? titles[0]
      : `${titles.slice(0, -1).join(", ")} and ${titles[titles.length - 1]}`;
  const folders = [...new Set(found.map((s) => s.folder))];
  return `${found.length === 1 ? "One save" : `${found.length} saves`}: ${list}. ${folders.length === 1 ? `In ${folders[0]}.` : `In ${folders.join(" and ")}.`}`;
}
